<template><div class="page"><v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center"><div><div class="text-overline">ORGANIZATION</div><h1 class="text-h5 font-weight-bold">Branches</h1><div class="grey--text">View offices, assigned users and projects.</div></div><v-spacer/><v-btn icon :loading="loading" @click="load"><v-icon>mdi-refresh</v-icon></v-btn></div></v-card><v-card flat outlined class="mb-4"><v-card-text><v-row dense><v-col cols="12" md="8"><v-text-field v-model="search" outlined dense clearable label="Search branch name or code" prepend-inner-icon="mdi-magnify" @keyup.enter="load" @click:clear="load"/></v-col><v-col cols="12" md="4"><v-select v-model="active" :items="activeOptions" item-text="text" item-value="value" outlined dense clearable label="Status" @change="load"/></v-col></v-row></v-card-text></v-card><v-card flat outlined><v-data-table :headers="headers" :items="items" :loading="loading" :options.sync="options" :server-items-length="total"><template v-slot:item.is_head_office="{item}"><v-chip v-if="item.is_head_office" x-small color="primary" dark>Head Office</v-chip><span v-else>—</span></template><template v-slot:item.is_active="{item}"><v-chip x-small :color="item.is_active?'success':'grey'" dark>{{item.is_active?'Active':'Inactive'}}</v-chip></template><template v-slot:item.actions="{item}"><v-btn icon small @click="view(item)"><v-icon small>mdi-eye</v-icon></v-btn></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="760"><v-card v-if="selected"><v-card-title>{{selected.name}}<v-spacer/><v-btn icon @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text><v-row><v-col cols="12" md="6"><strong>Code:</strong> {{selected.code||'—'}}</v-col><v-col cols="12" md="6"><strong>Manager:</strong> {{selected.manager_name||'—'}}</v-col><v-col cols="12" md="6"><strong>Phone:</strong> {{selected.phone||'—'}}</v-col><v-col cols="12" md="6"><strong>Email:</strong> {{selected.email||'—'}}</v-col><v-col cols="12"><strong>Address:</strong> {{selected.address||selected.city||'—'}}</v-col></v-row><v-divider class="my-4"/><div class="subtitle-1 font-weight-bold mb-2">Active Users ({{(selected.users||[]).length}})</div><v-chip v-for="u in selected.users||[]" :key="u.id" small class="mr-2 mb-2">{{u.name}}</v-chip><div class="subtitle-1 font-weight-bold mt-3 mb-2">Projects ({{(selected.projects||[]).length}})</div><v-chip v-for="p in selected.projects||[]" :key="p.id" small outlined class="mr-2 mb-2">{{p.name}}</v-chip></v-card-text></v-card></v-dialog></div></template><script>import api from '../../../services/api';export default{name:'Branches',data:()=>({loading:false,dialog:false,selected:null,search:'',active:null,items:[],total:0,options:{page:1,itemsPerPage:15},activeOptions:[{text:'Active',value:1},{text:'Inactive',value:0}],headers:[{text:'Code',value:'code'},{text:'Branch',value:'name'},{text:'City',value:'city'},{text:'Manager',value:'manager_name'},{text:'Office',value:'is_head_office'},{text:'Status',value:'is_active'},{text:'',value:'actions',sortable:false}]}),watch:{options:{deep:true,handler(){this.load()}}},mounted(){this.load()},methods:{async load(){this.loading=true;try{const params={search:this.search,page:this.options.page,per_page:this.options.itemsPerPage};if(this.active!==null)params.is_active=this.active;const r=await api.get('/branches',{params});this.items=r.data.data||[];this.total=r.data.total||0}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to load branches.')}finally{this.loading=false}},async view(item){try{const r=await api.get('/branches/'+item.id);this.selected=r.data.data;this.dialog=true}catch(e){this.$root.$emit('show-error','Unable to load branch details.')}}}}</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>